const $=id=>document.getElementById(id), E=NewsEngine;
let history=[],trained=null,lastResult=null;
try{history=JSON.parse(localStorage.getItem('newslens-history')||'[]');if(!Array.isArray(history))history=[];trained=JSON.parse(localStorage.getItem('newslens-model')||'null');}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true;}catch{return false;}}
function page(id){document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!==id);document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===id));if(id==='history')renderHistory();}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>page(b.dataset.page));
function count(){$('wordCount').textContent=E.tokens($('news').value).length+' words';}
$('news').oninput=count;$('textTab').onclick=()=>$('news').focus();
$('clear').onclick=()=>{$('news').value='';count();$('error').textContent='';$('result').hidden=true;$('empty').hidden=false;lastResult=null;};
const examples={viral:'SHOCKING!! A miracle device can power your entire home forever without any fuel. Experts say it is 100% guaranteed. Share this with everyone before they delete it!',report:'The city council published its annual transport report on Tuesday. The document lists spending on bus routes and includes a breakdown of maintenance costs. Residents can review the report and submit feedback before the next meeting.'};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('news').value=examples[b.dataset.example];count();$('news').focus();});
$('textFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>120000){$('error').textContent='Please choose a text file under 120 KB.';return;}const t=await f.text();if(t.length>30000){$('error').textContent='Maximum 30,000 characters.';return;}$('news').value=t;count();$('error').textContent='';e.target.value='';};
$('analyzeBtn').onclick=async()=>{const text=$('news').value.trim();if(E.tokens(text).length<8){$('error').textContent='Please add at least 8 words for a useful analysis.';return;}$('error').textContent='';$('analyzeBtn').disabled=true;$('analyzeBtn').textContent='Analyzing language patterns…';$('resultPanel').classList.add('scan');await new Promise(r=>setTimeout(r,1000));try{const sig=E.signals(text);const pred=trained?E.predict(trained.model,text):null;let title=pred?(pred.label==='unknown'?'Not enough familiar words':`Model prediction: ${pred.label.toUpperCase()}`):(sig.length?'Worth a closer look':'No listed red flags found');let desc=pred?'Dataset-based classification, not a verified fact-check.':'Language signals only. Neutral wording can still contain false claims.';lastResult={text,title,signals:sig,mode:pred?'Trained Naive Bayes':'Language rules',at:new Date().toISOString()};$('empty').hidden=true;$('result').hidden=false;$('result').innerHTML=`<div class="risk-count">${pred?'CUSTOM ML MODEL':'LANGUAGE SIGNALS · NO MODEL TRAINED'}</div><h3 class="score-title">${esc(title)}</h3><p class="muted">${desc}</p><div class="risk-count">${sig.length} LANGUAGE FLAGS · ${E.tokens(text).length} WORDS${pred?' · '+pred.unique+' KNOWN TERMS':''}</div>${sig.map(s=>`<div class="signal"><strong>⚑ ${esc(s.title)}</strong><span>${esc(s.detail)}</span></div>`).join('')}<div class="signal"><strong>⌕ What to check next</strong><span>Find the original publisher, check the date, and compare the claim with primary evidence and independent reporting.</span></div><div class="result-actions"><button class="secondary" id="export">Download report ↓</button></div>`;$('export').onclick=()=>download('newslens-report.txt',`${lastResult.title}\nMode: ${lastResult.mode}\nTime: ${lastResult.at}\n\n${text}\n\n${sig.map(x=>x.title+': '+x.detail).join('\n')}\n\nThis is not a fact-check. Verify original sources.`);history.unshift(lastResult);history=history.slice(0,30);if(!save('newslens-history',history))$('error').textContent='Analysis completed; browser storage is full so history was not saved.';renderHistory();}finally{$('resultPanel').classList.remove('scan');$('analyzeBtn').disabled=false;$('analyzeBtn').innerHTML='✦ Analyze news <span>→</span>';}};
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderHistory(){$('historyCount').textContent=history.length;$('historyList').innerHTML=history.length?history.map((h,i)=>`<div class="history-item"><div><small>${esc(new Date(h.at).toLocaleString())} · ${esc(h.mode)}</small><h3>${esc(h.title)}</h3><p>${esc(h.text.slice(0,180))}${h.text.length>180?'…':''}</p></div><button class="secondary" data-reopen="${i}">Reopen ↗</button></div>`).join(''):'<div class="panel lab"><h2>A fresh start.</h2><p>Your analyzed stories will appear here.</p></div>';document.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>{$('news').value=history[+b.dataset.reopen].text;count();page('analyze');$('result').hidden=true;$('empty').hidden=false;});}
$('deleteHistory').onclick=()=>{history=[];save('newslens-history',history);renderHistory();};
function modelUI(){$('modeLabel').textContent=trained?'Custom ML model':'Language signals';if(!trained){$('metrics').innerHTML='<p>Evaluation will appear here after training.</p>';return;}let s=trained.stats;const pct=n=>n===null?'N/A':(100*n).toFixed(1)+'%';$('metrics').innerHTML=`<div class="metric-grid"><div><b>${pct(s.accuracy)}</b><small>Test accuracy</small></div><div><b>${pct(s.precision)}</b><small>Fake precision</small></div><div><b>${pct(s.recall)}</b><small>Fake recall</small></div></div><p>${s.train} training articles · ${s.test} held-out test articles</p><p class="muted">One fixed split, seed 42. Results depend on your dataset and may not generalize.</p>`;$('trainStatus').textContent='Custom model ready. Return to Analyzer to use it.';}
$('dataset').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Maximum CSV size is 2 MB.');$('trainStatus').textContent='Preparing dataset and training…';const text=await f.text();const rows=E.dataset(text);const result=E.evaluate(rows);trained=result;modelUI();if(!save('newslens-model',result))$('trainStatus').textContent='Trained for this session only: browser storage is full.';}catch(err){$('trainStatus').textContent=err.message;}finally{e.target.value='';}};
$('resetModel').onclick=()=>{trained=null;save('newslens-model',null);modelUI();$('trainStatus').textContent='Model removed. Language rules are active.';};
$('template').onclick=()=>download('dataset-format.csv','text,label\n"Example factual article text goes here with a verified source",real\n"Example fabricated article text goes here with a verified label",fake\n');
renderHistory();modelUI();
const canvas=$('network'),ctx=canvas.getContext('2d');let dots=[];function resize(){canvas.width=innerWidth;canvas.height=innerHeight;dots=Array.from({length:40},()=>({x:Math.random()*canvas.width,y:Math.random()*canvas.height,vx:(Math.random()-.5)*.18,vy:(Math.random()-.5)*.18}));}resize();window.addEventListener('resize',resize);function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);for(const d of dots){d.x=(d.x+d.vx+canvas.width)%canvas.width;d.y=(d.y+d.vy+canvas.height)%canvas.height;ctx.fillStyle='#9fe3c4';ctx.beginPath();ctx.arc(d.x,d.y,1.5,0,7);ctx.fill();for(const b of dots){const dist=Math.hypot(d.x-b.x,d.y-b.y);if(dist<150){ctx.strokeStyle=`rgba(130,210,170,${(1-dist/150)*.25})`;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}}requestAnimationFrame(draw);}if(!matchMedia('(prefers-reduced-motion: reduce)').matches)draw();
